local CandlestickMaker = {}
local PRODUCTS = {
    simple_clay_candlestick = { name = "Preprost glineni svečnik", clayCost = 2, waxCost = 1, time = 3, cost = 40, lightRadius = 18, happiness = 1, description = "Preprost glineni svečnik za sveče." },
    brass_candlestick = { name = "Medeninast svečnik", brassCost = 2, clayCost = 1, waxCost = 1, time = 5, cost = 110, lightRadius = 30, happiness = 1, prestige = 2, description = "Medeninast svečnik za trgovce." },
    silver_trimmed_candlestick = { name = "Srebrnoobrobljeni svečnik", silverCost = 1, brassCost = 2, clayCost = 1, waxCost = 1, time = 8, cost = 280, lightRadius = 42, happiness = 2, prestige = 6, description = "Srebrnoobrobljeni svečnik za plemiče." },
    gold_trimmed_candlestick = { name = "Zlatookrasni svečnik", goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, waxCost = 1, time = 12, cost = 680, lightRadius = 55, happiness = 3, prestige = 14, description = "Zlatookrasni svečnik za visoke plemiče." },
    jewel_set_candlestick = { name = "Draguljasta svečnik", goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, waxCost = 1, jewelCost = 1, time = 16, cost = 1500, lightRadius = 70, happiness = 5, prestige = 27, description = "Svečnik z draguljem za visoko plemstvo." },
    royal_grand_candlestick = { name = "Kraljevski veliki svečnik", goldCost = 2, silverCost = 2, brassCost = 2, clayCost = 1, waxCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3500, lightRadius = 88, happiness = 12, prestige = 58, description = "Veliki kraljevski svečnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    candlestick_workshop = { name = "Svečniška delavnica", cost = { gold = 240, wood = 100, stone = 120, clay = 6, wax = 6 }, upkeep = 5, qualityBonus = 5 },
    lighting_loft = { name = "Razsvetljena podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    master_candlestick_atelier = { name = "Mojstrski svečniški atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_lighting_palace = { name = "Kraljevska razsvetljenska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
CandlestickMaker.clayStock = 14; CandlestickMaker.waxStock = 10; CandlestickMaker.brassStock = 12; CandlestickMaker.silverStock = 6; CandlestickMaker.goldStock = 6; CandlestickMaker.jewelStock = 4; CandlestickMaker.pearlStock = 4
CandlestickMaker.productStock = {}; CandlestickMaker.buildings = {}; CandlestickMaker.maker = nil; CandlestickMaker.activeMaking = {}; CandlestickMaker.totalProducts = 0; CandlestickMaker.dayTimer = 0
function CandlestickMaker.init() CandlestickMaker.clayStock=14; CandlestickMaker.waxStock=10; CandlestickMaker.brassStock=12; CandlestickMaker.silverStock=6; CandlestickMaker.goldStock=6; CandlestickMaker.jewelStock=4; CandlestickMaker.pearlStock=4; CandlestickMaker.productStock={}; CandlestickMaker.buildings={}; CandlestickMaker.maker=nil; CandlestickMaker.activeMaking={}; CandlestickMaker.totalProducts=0; CandlestickMaker.dayTimer=0; print("[CandlestickMaker] Royal Candlestick Maker System initialized (6 products, 4 buildings)") end
function CandlestickMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CandlestickMaker.maker={name=n or ("Svečničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svečničar najet: %s (spretnost: %d)",CandlestickMaker.maker.name,s),"success") end; return true end
function CandlestickMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CandlestickMaker.build(id) local ok,e=CandlestickMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CandlestickMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CandlestickMaker.getQualityBonus() local b=0; for _,bd in ipairs(CandlestickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CandlestickMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and CandlestickMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.waxCost and CandlestickMaker.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.brassCost and CandlestickMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and CandlestickMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CandlestickMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CandlestickMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CandlestickMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CandlestickMaker.buildings==0 then return false,"Potrebna svečniška delavnica" end; if not CandlestickMaker.maker then return false,"Potreben svečničar" end; return true end
function CandlestickMaker.make(pt,qty) qty=qty or 1; local ok,e=CandlestickMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then CandlestickMaker.clayStock=CandlestickMaker.clayStock-d.clayCost*qty end; if d.waxCost then CandlestickMaker.waxStock=CandlestickMaker.waxStock-d.waxCost*qty end; if d.brassCost then CandlestickMaker.brassStock=CandlestickMaker.brassStock-d.brassCost*qty end; if d.silverCost then CandlestickMaker.silverStock=CandlestickMaker.silverStock-d.silverCost*qty end; if d.goldCost then CandlestickMaker.goldStock=CandlestickMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CandlestickMaker.jewelStock=CandlestickMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CandlestickMaker.pearlStock=CandlestickMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CandlestickMaker.maker then t=math.max(1,t-math.floor(CandlestickMaker.maker.skill/13)) end; table.insert(CandlestickMaker.activeMaking,{id="candlestick_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CandlestickMaker.completeMaking(m) local q=1.0+(CandlestickMaker.getQualityBonus()/100); if CandlestickMaker.maker then q=q+(CandlestickMaker.maker.skill/140) end; q=math.min(2.5,q); CandlestickMaker.productStock[m.productType]=(CandlestickMaker.productStock[m.productType] or 0)+m.quantity; CandlestickMaker.totalProducts=CandlestickMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CandlestickMaker.maker then CandlestickMaker.maker.itemsMade=CandlestickMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CandlestickMaker.maker.skill=math.min(100,CandlestickMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svečnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"candlestick.completed",{productName=m.productName,lightRadius=m.lightRadius,prestige=m.prestige,happiness=m.happiness}) end end
function CandlestickMaker.update(dt) if not _G.state then return end; CandlestickMaker.dayTimer=CandlestickMaker.dayTimer+dt; if CandlestickMaker.dayTimer>=30 then CandlestickMaker.dayTimer=0; for i=#CandlestickMaker.activeMaking,1,-1 do local m=CandlestickMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CandlestickMaker.completeMaking(m); table.remove(CandlestickMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CandlestickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CandlestickMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CandlestickMaker.getStats() return {clayStock=CandlestickMaker.clayStock,waxStock=CandlestickMaker.waxStock,brassStock=CandlestickMaker.brassStock,silverStock=CandlestickMaker.silverStock,goldStock=CandlestickMaker.goldStock,jewelStock=CandlestickMaker.jewelStock,pearlStock=CandlestickMaker.pearlStock,productStock=CandlestickMaker.productStock,numBuildings=#CandlestickMaker.buildings,hasMaker=CandlestickMaker.maker~=nil,makerName=CandlestickMaker.maker and CandlestickMaker.maker.name or "—",makerSkill=CandlestickMaker.maker and CandlestickMaker.maker.skill or 0,activeMaking=#CandlestickMaker.activeMaking,totalProducts=CandlestickMaker.totalProducts} end
return CandlestickMaker
